  "exports.createBusinessFirst": "پہلے کاروبار بنائیں — ایکسپورٹس کسی کاروبار سے تعلق رکھتی ہیں، ایپ سے نہیں۔",
  "exports.lockedTitle": "CSV اور Excel ایکسپورٹس Business کی خصوصیت ہے",
  "exports.lockedDesc": "آپ کا ورک اسپیس Essentials پلان پر ہے۔ Business میں CSV اور Excel ایکسپورٹس، اسٹاک کی قدر کا اندازہ، لامحدود مصنوعات اور عملہ، سپلائرز، خریداری اور بنڈلز شامل ہوتے ہیں۔",
  "exports.seeBusiness": "دیکھیں Business میں کیا شامل ہے",
  "exports.whatTheseAre": "یہ فائلیں کیا ہیں",
  "exports.about1": "ہر ڈیٹا سیٹ CSV یا اصل Excel ورک بک (.xlsx) کے طور پر آتا ہے — مکمل انوینٹری ورک بک صرف Excel میں ہوتی ہے، ہر ڈیٹا سیٹ کے لیے ایک الگ شیٹ کے ساتھ۔ CSV فائلیں Excel، Numbers، Google Sheets اور بیشتر اسٹاک ایپس میں کھلتی ہیں۔ UTF-8 متن، کوٹس میں کومے، نوٹس میں لائن بریکس اور کوڈز کے ابتدائی صفر سب محفوظ رہتے ہیں، اور جو سیلز فارمولے جیسے شروع ہوتے ہیں انہیں بے اثر کر دیا جاتا ہے تاکہ اسپریڈشیٹ انہیں متن کے طور پر کھولے۔",
  "exports.about2": "Excel فائلوں میں SKUs، UPCs، ISBNs اور بارکوڈز متن والے سیلز ہوتے ہیں — کبھی سائنسی نوٹیشن میں نہیں اور کبھی صفر کٹے ہوئے نہیں — کالم کی چوڑائی، ہیڈر فلٹرز اور کرنسی یا مقدار کے فارمیٹس کے ساتھ۔ مکمل انوینٹری ورک بک میں مصنوعات، اسٹاک کی سطحیں، مقامات اور نقل و حرکت الگ الگ شیٹس پر رہتی ہیں۔",
  "exports.about3": "بہت بڑی ایکسپورٹس ہر ڈیٹا سیٹ کے لیے 20,000 قطاروں پر رک جاتی ہیں — جب ایسا ہوتا ہے تو فائل کا نام یہ بتاتا ہے (truncated-20000)، تاکہ جزوی فائل کبھی مکمل نہ سمجھی جائے۔",
  "exports.about4": "بیک اپ آپ کے ڈیٹا کی ایک جھلک ہے، ایک کلک سے بحالی نہیں۔ اسے بحال کرنا دستی، پہلے جائزہ لینے والا کام ہے، اس لیے فائل کو محفوظ رکھیں — ایپ میں ابھی تک اس سے حذف شدہ کاروبار دوبارہ نہیں بنایا جا سکتا۔ ایپ کوڈ اور Base44 پلیٹ فارم کے بیک اپس ان فائلوں سے الگ سنبھالے جاتے ہیں۔",
  "exports.about5": "تصاویر اور منسلکات ان کے محفوظ کردہ لنکس کے طور پر درج ہوتے ہیں — تصویری فائلیں خود ڈاؤن لوڈ میں شامل نہیں ہوتیں۔",
  "exports.backupTitle": "مکمل بیک اپ",
