  "settings.cancelTerms.noApprovalTitle": "بغیر منظوری کے منسوخ کریں:",
  "settings.cancelTerms.paymentBody": "ادا شدہ آزمائشوں کے لیے، سات دن کی آزمائش کے لیے سائن اپ کے وقت ادائیگی کا طریقہ درکار ہوتا ہے۔ اگر آزمائش کی منسوخی کی مقررہ آخری تاریخ کے اندر منسوخ نہ کیا جائے تو آزمائش کے بعد منتخب ماہانہ پلان کا خودکار چارج لگ جائے گا۔ قیمت، پہلی بلنگ کی تاریخ، اور فراہم کنندہ کے مطابق منسوخی کی آخری تاریخ سائن اپ کے دوران دکھائی جانی چاہیے۔ آزمائشی بلنگ Stripe کے ذریعے ہوتی ہے۔",
  "settings.cancelTerms.paymentTitle": "ادائیگی کا طریقہ اور خودکار تجدید:",
  "settings.cancelTerms.remainingBody": "اگر آپ بلنگ کی مدت کے لیے پہلے ہی ادائیگی کر چکے ہیں تو آپ تصدیق شدہ ادا شدہ تاریخ تک رسائی برقرار رکھ سکتے ہیں۔ اس سے پہلے ختم کرنے کے لیے فراہم کنندہ کی مناسب تصدیق اور قابل اطلاق رقم کی واپسی کی کارروائی درکار ہوتی ہے۔ مفت آزمائش کی رسائی فراہم کنندہ کی تصدیق شدہ آزمائش ختم ہونے کی تاریخ کے مطابق ختم ہوتی ہے۔",
  "settings.cancelTerms.remainingTitle": "بقیہ رسائی:",
  "settings.cancelTerms.storesBody": "اگر آپ کبھی Google Play یا Apple App Store کے ذریعے سبسکرائب کریں تو آپ کی سبسکرپشن اسی اسٹور کے ذریعے بل اور منظم ہوتی ہے۔ ہو سکتا ہے آپ کو اسے سبسکرپشن کے لیے استعمال کیے گئے اسی Google یا Apple اکاؤنٹ کے سبسکرپشنز والے حصے میں براہ راست منسوخ کرنا پڑے۔ الگ ویب سائٹ سبسکرپشن منسوخ کرنا، اس ایپ کو ان انسٹال کرنا، یا Luminous StockHaven اکاؤنٹ حذف کرنے کی درخواست کرنا اسٹور سے بل ہونے والی سبسکرپشن کو خودکار طور پر منسوخ نہیں کرتا۔ اپنی خریداری کی رسید دیکھ کر تصدیق کریں کہ آپ کو بل کون بھیجتا ہے۔",
