  "staff.access.noSeatBody": "آپ کے اکاؤنٹ کے پاس اس کاروبار کے لیے عملے کی کوئی نشست نہیں، اس لیے اس کا اسٹاک بند رہتا ہے۔ مالک سے کہیں کہ وہ آپ کو عملہ اور کردار میں شامل کرے۔",
