  "staff.access.suspendedBody": "کسی منتظم نے فعال کاروبار کے لیے اس عملے کے اکاؤنٹ کو معطل کر دیا ہے۔ ان سے کہیں کہ آپ کو دوبارہ فعال کر دیں، پھر دوبارہ سائن ان کریں۔",
  "staff.access.suspendedTitle": "آپ کی رسائی موقوف ہے",
  "staff.addFirst": "پہلا عملے کا رکن شامل کریں",
  "staff.addMember": "عملے کا رکن شامل کریں",
  "staff.emptyBody": "ایک شخص شامل کریں، اسے ایک کردار اور اس کے ساتھ جڑی اجازتیں دیں، اور اسے اس کاروبار میں سائن ان کے لیے ای میل کے ذریعے دعوت دی جاتی ہے۔",
  "staff.emptyTitle": "ابھی کوئی عملہ نہیں",
  "staff.eyebrow": "ٹیم",
  "staff.how.p1": "ہر رکن کا ایک کردار اور اس کی اپنی اجازتوں کی فہرست ہوتی ہے، اس لیے آپ کسی کردار سے شروع کر کے نیا کردار بنائے بغیر ایک چیز بدل سکتے ہیں۔ کسی کردار میں ترمیم کرنے سے اس پر پہلے سے موجود ارکان دوبارہ نہیں لکھے جاتے — ان کی کردار کی ڈیفالٹ اقدار دوبارہ لاگو کرنے کے لیے رکن کو کھولیں۔",
  "staff.how.p2": "اپنی پسند کے کردار ایک Business خصوصیت ہیں: Essentials پانچ بلٹ ان کردار استعمال کرتا ہے (مالک، مینیجر، اسٹاک کلرک، سیلز کلرک، دیکھنے والا)۔",
  "staff.how.p3": "دعوتیں ای میل کے ذریعے بھیجی جاتی ہیں۔ کوئی رکن صرف قبول کرنے کے بعد ہی سائن ان کر سکتا ہے، اور کسی کو اس فہرست سے ہٹانے سے اس کا ایپ اکاؤنٹ حذف نہیں ہوتا۔",
  "staff.how.p4": "اسٹور وہ مقام ہے جہاں کسی شخص کو تعینات کیا جاتا ہے۔ یہ اس کے کارڈ پر درج ہوتا ہے؛ وہ کیا کھول سکتا ہے اس کا فیصلہ پھر بھی اس کے کردار اور اجازتوں سے ہوتا ہے۔",
  "staff.how.p5": "اجازتیں فیصلہ کرتی ہیں کہ ہر شخص کیا کھول سکتا ہے: اس کے کردار سے باہر کے مینو آئٹم چھپے رہتے ہیں، اور مسدود پتا صفحے کے بجائے “آپ کے کردار پر نہیں” کا نوٹس دکھاتا ہے۔ تبدیلی اگلی بار اس شخص کے ایپ لوڈ کرنے پر لاگو ہوتی ہے؛ کسی رکن کو معطل کرنے سے وہ مکمل طور پر باہر بند ہو جاتا ہے۔",
  "staff.how.p6": "منتظمین تمام ڈیٹا دیکھ اور بدل سکتے ہیں، ایپ صارفین اور کردار منظم کر سکتے ہیں، اور کسی عملے کے کردار سے کبھی محدود نہیں ہوتے۔ جس کے پاس عملے کا کوئی ریکارڈ نہیں — نئے کاروبار کا مالک — اسے مکمل رسائی حاصل رہتی ہے۔",
