  "settings.security.changedOk": "Done — your account email is now {email}. A notice was sent to your old address.",
  "training.lessons.lost-email-recovery.step1": "Do not panic, and do not make a new account — a new email starts a totally new, empty storefront. Your shop is still exactly where you left it.",
  "training.lessons.lost-email-recovery.step2": "On the sign-in page, tap “Can’t get into your email?” Enter your account email and use one spare key: a backup code, or a 6-digit code sent to your backup email.",
  "training.lessons.lost-email-recovery.step3": "That opens ONE step only: changing your account email. Enter an email you can reach and enter the code sent to it. Your shop, inventory, team and history all move to the new email — nothing is lost.",
  "training.lessons.lost-email-recovery.step4": "When it finishes, you are signed in normally again. Go straight to Settings → Security & spare keys and set up fresh spare keys for the new email.",
  "training.lessons.lost-email-recovery.title": "If you lose access to your email",
  "training.lessons.owner-staff-email-fix.step1": "If a team member loses access to the email they were added under, they may not need you at all: their own spare keys (backup codes or a backup email, in their Settings → Security) let them change the account email themselves from the sign-in page.",
  "training.lessons.owner-staff-email-fix.step2": "If they never set spare keys up, you can fix it for them: open Staff, open their record, and change the email there. The app moves their whole world with it — their account, their rows at your other stores, and their trial history.",
  "training.lessons.owner-staff-email-fix.step3": "The move is all-or-nothing on purpose: they will never have access under both emails, and no duplicate account is created. Their live sign-ins keep working; a notice is sent to the old address.",
  "training.lessons.owner-staff-email-fix.step4": "Afterwards, ask them to sign in and set up their spare keys (their training has a lesson on it), so next time they can rescue themselves in two minutes.",
  "training.lessons.owner-staff-email-fix.title": "When a team member is locked out: fixing their email",
  "training.lessons.spare-keys-setup.step1": "Your account lives under your email. If you ever lose access to that email — locked out, changed providers, anything — your spare keys are how you get back in. Set them up now, while everything works.",
  "training.lessons.spare-keys-setup.step2": "Open Settings and find Security & spare keys. Choose Generate backup codes: you will see ten one-time codes. They are shown only once, so print them or write them down and keep them somewhere safe.",
  "training.lessons.spare-keys-setup.step3": "In the same section, add a backup email — a second address you control — and enter the 6-digit code we send there to verify it. Either spare key can rescue you; both together is best.",
  "training.lessons.spare-keys-setup.step4": "Never share your codes with anyone, and never type them anywhere except this app’s recovery page. If your codes run low, generate a fresh set — the old ones stop working.",
  "training.lessons.spare-keys-setup.title": "Your spare keys: set them up before you need them",
  "purchasing.sendOrder": "Send order",
  "purchasing.sendAgain": "Send again",
  "purchasing.sentFlash": "Order {number} emailed to {email}.",
  "purchasing.sentTo": "Sent to {email} · {date}",
  "purchasing.sendFailed": "The order could not be sent.",
  "training.lessons.mgr-send-supplier-order.step1": "Once an order is placed, tap Send order on the Purchasing page and it goes straight to the supplier from inside the app. A draft cannot be sent — place it first.",
  "training.lessons.mgr-send-supplier-order.step2": "The supplier needs an email address on their Suppliers record. If it is missing, the app stops and tells you to add it first — nothing is ever sent quietly or marked sent when it was not.",
  "training.lessons.mgr-send-supplier-order.step3": "The supplier receives an email with the order PDF attached, under THIS store’s name only — the email and the document carry the business’s name, never the app’s.",
  "training.lessons.mgr-send-supplier-order.step4": "The order then shows who it was sent to and when, and you can send it again if something changed. If a supplier makes you order through their own website, keep doing that — sending from here is a choice, never a lock-in.",
  "training.lessons.mgr-send-supplier-order.title": "Sending an order to the supplier",
  "training.lessons.owner-send-supplier-order.step1": "Any placed purchase order can be emailed to its supplier from the Purchasing page — no printing it out, no separate email app. Sending lives with Suppliers & purchasing, on the Business plan.",
  "training.lessons.owner-send-supplier-order.step2": "Sending needs the supplier’s email address on their record. Without one, the app refuses plainly and tells you to add it first, and an order is only ever recorded as sent after the email truly goes out.",
  "training.lessons.owner-send-supplier-order.step3": "What the supplier receives carries your business’s name only — your name is on the email and on the attached order PDF; the app’s name appears nowhere on what they see.",
  "training.lessons.owner-send-supplier-order.step4": "Every send is recorded on the order itself — sent, when, and to which address — and re-sending updates it. Suppliers who require ordering through their own website keep that flow; sending from the app never replaces or blocks it.",
  "training.lessons.owner-send-supplier-order.title": "Emailing orders to suppliers (Business plan)",
  "training.lessons.owner-trial-reminders.step1": "While your own 7-day trial runs, the app reminds you itself — two emails to the address you subscribed with: one on day 4 of the trial, and one 24 hours before the trial ends. No other emails, and paid plans never get reminders at all.",
  "training.lessons.owner-trial-reminders.step2": "Inside the app, three short notices appear one at a time as the end approaches: \"You have 5 more days left on your trial.\", then \"You have 3 more days left on your trial.\", then \"24 hours until your trial ends.\" The moment the trial ends or turns into a paid plan, they are gone.",
  "training.lessons.owner-trial-reminders.step3": "Cancelling lives in Settings, under Billing. If you cancel during the trial, you still keep the full 7 days — and because you cancelled, the last email changes its tune: it tells you plainly that no charge is coming and your plan simply ends.",
  "training.lessons.owner-trial-reminders.step4": "Each reminder email is sent exactly once — the app keeps a record of what was sent, so restarts and repeat checks never email you twice. Your customers on trials get the very same reminders for their own subscriptions.",
  "training.lessons.owner-trial-reminders.title": "Your trial reminders: what arrives, and when",
  "settings.delete.cancelFirstHeadline": "Cancel your subscription BEFORE you delete.",
  "settings.delete.cancelFirstBody": "You're deleting your account — that doesn't mean you're canceling your subscription. Cancel your subscription first, then delete your account whenever you're ready.",
  "plansLib.businessIncludes.rewards": "Staff rewards and incentives",
