  "rewards.slip.show": "Show this code at the till.",
  "rewards.status.active": "Ready to use",
  "rewards.status.redeemed": "Used",
  "rewards.status.void": "Void",
  "rewards.subtitle": "Say thank you with a reward — a percent off, a gift card, or anything you describe.",
  "rewards.title": "Rewards & incentives",
  "rewards.value.giftCard": "{value} gift card",
  "rewards.value.percentOff": "{percent}% off in store",
  "rewards.void": "Void",
  "rewards.voided": "Reward voided.",
  "workforce.tab.rewards": "Rewards",
  "training.lessons.mgr-give-rewards.step1": "Open Workforce and tap Rewards. Pick the team member, then the kind: a percent off in store, a gift card, or something else you describe in your own words.",
  "training.lessons.mgr-give-rewards.step2": "Give the reward a short name and a note if you like. The person gets a bell right away, and the reward waits in their My rewards with its own code.",
  "training.lessons.mgr-give-rewards.step3": "The boundary, by design: you reward STAFF only. You cannot reward yourself or another manager — rewarding a manager is the owner’s call, and the app will refuse it plainly.",
  "training.lessons.mgr-give-rewards.step4": "At the till, type the code the team member shows you and mark it used — each code works once. You can void a reward you gave if plans change; the owner’s gifts are the owner’s to void.",
  "training.lessons.mgr-give-rewards.title": "Giving rewards to your staff",
  "training.lessons.owner-give-rewards.step1": "Rewards live in Workforce, on the Rewards tab, and they are Business-plan only — on Essentials the tab shows a locked door, so your team can see what the bigger plan holds.",
  "training.lessons.owner-give-rewards.step2": "You can reward ANYONE on the team — staff and managers alike. Pick the person, then the kind: a percent off in store (any percent you choose), a gift card to anywhere, or any incentive you describe in your own words.",
  "training.lessons.owner-give-rewards.step3": "The reward lands with its own one-time code and rings the person’s bell. They show the code at the till; an owner or manager types it in to mark it used.",
  "training.lessons.owner-give-rewards.step4": "A printed or shared reward slip carries YOUR business’s name only — never the app’s. It is your store’s thank-you, not an advertisement.",
  "training.lessons.owner-give-rewards.title": "Giving rewards (Business plan)",
  "training.lessons.owner-rewards-oversight.step1": "Your manager can give rewards too — to staff only. The app refuses a manager rewarding themselves or another manager; rewarding a manager is always your call.",
  "training.lessons.owner-rewards-oversight.step2": "You see every reward in the business in the Rewards history: who gave it, who got it, and whether it is ready, used or void. A manager sees only the rewards they gave and the ones they received.",
  "training.lessons.owner-rewards-oversight.step3": "You can void any reward, including one your manager gave. A manager can void their own gifts, but never yours.",
  "training.lessons.owner-rewards-oversight.step4": "Each code works exactly once, and a voided reward can never be used — the history always shows which way a reward ended.",
  "training.lessons.owner-rewards-oversight.title": "Overseeing rewards: your manager’s giving",
  "training.lessons.staff-your-rewards.step1": "When your manager or the owner gives you a reward, your bell rings. Open Workforce and tap Rewards to see it under My rewards.",
  "training.lessons.staff-your-rewards.step2": "Every reward has its own code. Keep it to yourself — whoever shows the code at the till is the one who uses the reward.",
  "training.lessons.staff-your-rewards.step3": "To use it, show the code when you buy. The person at the till types it in and marks it used — each code works exactly once.",
  "training.lessons.staff-your-rewards.step4": "Rewards are a Business-plan treat. If your store is not on Business, the Rewards tab shows a locked door instead — that is the plan, not a mistake.",
  "training.lessons.staff-your-rewards.title": "Your rewards: finding your code and using it",
  "training.module.rewards": "Rewards & incentives",
