  "pos.shopify.connect": "Connect Shopify",
  "pos.shopify.connectedToast": "Shopify connected. Its sales now count here.",
  "pos.shopify.domainPlaceholder": "your-store.myshopify.com",
  "pos.shopify.help": "Shopify POS sales are Shopify orders. Connect this store and every order takes its items out of stock here on its own.",
  "pos.shopify.tokenNote": "The token comes from a custom app in your Shopify admin. It is stored on the server only and never shown back.",
  "pos.shopify.tokenPlaceholder": "Access token from your Shopify custom app",
  "pos.square.connect": "Connect Square",
  "pos.square.connectedToast": "Square connected. Its sales now count here.",
  "pos.square.failedToast": "Square did not finish connecting. You can try again.",
  "pos.square.help": "Connect Square and every sale at the till takes its items out of stock here on its own — nothing to type in at the end of the day.",
  "pos.square.notConfigured": "Square connections are not switched on yet. The CSV import below works today.",
  "pos.subtitle": "Connect your till, and a sale at the register takes the item out of stock here by itself. Nothing ever counts twice.",
  "pos.title": "Till connections",
  "pos.webhookPending": "Sales webhooks are not switched on yet on our side — connections are saved, and sales start arriving the moment they are.",
  "training.lessons.owner-pos-connect-shopify.step1": "Till connections are part of the Business plan. Shopify POS sales are Shopify orders, so the connection is per store: in Shopify, create a custom app for your store and copy its access token. On the Till connections page, paste your store domain (like your-store.myshopify.com) and the token.",
  "training.lessons.owner-pos-connect-shopify.step2": "The token is stored on the server only — it is never shown back, not even to you. If you ever paste a new one, it simply replaces the old.",
  "training.lessons.owner-pos-connect-shopify.step3": "Pick which of your locations this store’s sales come out of, if you have more than one. Then every order — at the Shopify till or online — takes its items out of stock here on its own.",
  "training.lessons.owner-pos-connect-shopify.step4": "One store connects to one workspace here. If a domain is already connected somewhere else, the app says so plainly instead of sharing it.",
  "training.lessons.owner-pos-connect-shopify.title": "Connecting Shopify POS",
  "training.lessons.owner-pos-connect-square.step1": "Till connections are part of the Business plan. Open Till connections (in the Sales menu) and tap Connect on the Square card. You will land on Square’s own page to approve the connection — the app never sees your Square password.",
  "training.lessons.owner-pos-connect-square.step2": "Back in the app, the card shows Connected. If your store has more than one location, pick which one this till’s sales come out of; otherwise sales come out of your first location.",
  "training.lessons.owner-pos-connect-square.step3": "From then on, every Square sale takes the items out of stock here by itself. Sell one thing at the till and watch the Recent sales list on the same page: the sale lands within moments, marked as counted.",
  "training.lessons.owner-pos-connect-square.step4": "A sale can never count twice — if Square sends the same sale again, the app recognises it and changes nothing. Disconnecting is on the same card, and it stops the matching right away.",
  "training.lessons.owner-pos-connect-square.title": "Connecting Square: sales that move your stock for you",
  "training.lessons.owner-pos-csv.step1": "Any till that can export a sales file can still feed your inventory. Export the day’s sales as a CSV with these columns: sale_id, sold_at, sku_or_barcode, quantity — item_name and location help, but are optional.",
  "training.lessons.owner-pos-csv.step2": "Upload the file on the Till connections page. Each sale_id is recorded once: uploading the same file again tomorrow changes nothing, it only reports the duplicates.",
  "training.lessons.owner-pos-csv.step3": "Rows the app cannot use are never skipped quietly — a row with no sale_id, or a quantity that is not a number, is listed back to you with its row number and the reason.",
  "training.lessons.owner-pos-csv.step4": "Items are matched by SKU or barcode, exactly like a live till. Anything unmatched waits on the mapping screen, same as any other sale.",
  "training.lessons.owner-pos-csv.title": "No till API? The end-of-day CSV",
  "training.lessons.owner-pos-mapping.step1": "A till item matches your products by SKU or barcode. When a sale comes in with an item the app has never seen, that item is HELD — no stock moves, and the sale waits on the Till connections page under Items waiting to be matched.",
  "training.lessons.owner-pos-mapping.step2": "Pick which of your products that item really is, and save. That match is remembered for good: every future sale of that item counts by itself.",
  "training.lessons.owner-pos-mapping.step3": "After saving, tap Apply to held sales to count the sales that were waiting — they write their stock movements right then, with the sale’s own reference.",
  "training.lessons.owner-pos-mapping.step4": "If a held sale asks for more than is on the shelf, it stays marked as not enough stock instead of driving the count negative. Restock, then apply again from the same screen.",
  "training.lessons.owner-pos-mapping.title": "When a till item does not match: the mapping screen",
  "training.lessons.owner-pos-sales-list.step1": "The Recent sales list on the Till connections page shows every sale your tills sent: which till, the sale number, when, the total as the till reported it, and what happened to each item.",
  "training.lessons.owner-pos-sales-list.step2": "Counted means the stock moved. Part counted means some items counted and some are waiting or short — open the sale to see which, in plain words.",
  "training.lessons.owner-pos-sales-list.step3": "Held means nothing in that sale has counted yet: an item needs matching (see the mapping lesson), the shelf did not hold enough, or the sale arrived while the store was not on the Business plan. All three are fixable from the same page — a sale held for the plan counts from here once the store is back on Business — and nothing is ever lost silently.",
  "training.lessons.owner-pos-sales-list.step4": "Every counted sale writes a normal Sold entry in your stock history with a reference that names the till and the sale — so your Movements page and your till always tell the same story.",
  "training.lessons.owner-pos-sales-list.title": "Reading your till sales",
  "training.lessons.staff-pos-till-sales.step1": "If your store is on the Business plan and has connected its till (Square or Shopify POS), every sale at the register takes the item out of stock here on its own — no scanning out, no typing it in later.",
  "training.lessons.staff-pos-till-sales.step2": "You can watch it happen on the Till connections page: each sale shows what sold, how many, and whether it counted. A sale that counted shows as counted, in plain words.",
  "training.lessons.staff-pos-till-sales.step3": "Sometimes a sale is HELD instead: the till sold something the app could not match to a product yet. Nothing was taken out of stock — the sale waits until the owner or a manager matches that item once (the mapping screen). After that, it counts, and the next sale of the same item matches by itself.",
  "training.lessons.staff-pos-till-sales.step4": "If a held sale is about something you just sold, tell your manager or the owner — one quick match fixes it for good. Never adjust the stock by hand to make up for a held sale; that would count it twice once it is matched.",
  "training.lessons.staff-pos-till-sales.title": "When the till sells it, your stock moves itself",
